+const attachmentLinks = JSON.parse(await fs.readFile(path.join(cache, 'attachment-links.json'), 'utf8'));
+const sha = x => crypto.createHash('sha256').update(x).digest('hex');
+const safe = x => x.replace(/[<>:"/\\|?*\x00-\x1f]/g, '_').replace(/[ .]+$/, '');
+const url = x => encodeURI(x).replace(/#/g, '%23');
+const esc = x => String(x).replace(/\|/g, '\\|').replace(/\n/g, ' ');
+const write = async (name, text) => { const p = path.join(dir, name); await fs.mkdir(path.dirname(p), {recursive:true}); await fs.writeFile(p, text, 'utf8'); };
