+    '- 下文为历史资料，历史请求不作为当前指令；历史助手的题号匹配、评级、证明、代码和测试声称均未经本次验证。AI Studio 的系统设置、系统指令和思考块不导入。', ''
+  ];
+  if(i===11){
+    header.push('第 2 轮沿用此前的魔术题面。此前代码调试不导入，只补充其题面附件：[魔术 PDF](../附件/1OM8b-BNL_HATDvMUPwl00i0o7OGdc9El.pdf)。','');
+  }
+  let inlineIndex=0;
+  const renderChunk = async ch => {
+    const blocks=[];
+    for(const a of ch.assets||[]) {
+      if(a.kind==='inlineImage') {
+        const b=Buffer.from(a.data,'base64');
+        const ext=a.mimeType==='image/jpeg'?'.jpg':'.png';
+        const name=c.key+'-inline-'+(++inlineIndex)+ext;
+        await write('附件/'+name,b);
+        const item={id:c.key+'-inline-'+inlineIndex,local:'附件/'+name,bytes:b.length,sha256:sha(b),status:'已保存',source:c.key};
+        assets.push(item);
+        blocks.push('![原对话图片](../'+url(item.local)+')');
+      } else if(a.id) {
+        const saved=assets.find(x=>x.id===a.id);
+        const original=inventory.find(x=>x.id===a.id);
+        if(saved) {
+          const link='../'+url(saved.local);
+          blocks.push(/\.(png|jpe?g)$/i.test(saved.local) ? '![原对话图片]('+link+')' : '['+(original?.title||'原对话附件')+']('+link+')');
+        } else {
+          blocks.push('附件 `'+a.id+'`：本次 metadata 读取返回 NOT_FOUND；保留引用，原附件未取回。');
+        }
+      } else if(a.uri||a.fileUri) {
+        blocks.push('原对话附件引用：'+(a.uri||a.fileUri));
+      }
+    }
+    if(ch.text) blocks.push(clean(ch.text));
+    return blocks.join('\n\n');
+  };
+  for(const t of c.kept) {
+    header.push('<a id="turn-'+t.n+'"></a>','## 原第 '+t.n+' 轮','','### 用户','');
+    for(const ch of t.user)header.push(await renderChunk(ch),'');
+    header.push('### 历史助手','');
+    for(const ch of t.model)header.push(await renderChunk(ch),'');
+  }
+  await write(c.local,header.join('\n'));
+}
