import path from 'node:path';
import crypto from 'node:crypto';
const base=path.resolve('outputs/历史对话/2026-10-27-云端归档');
const m=JSON.parse(await fs.readFile(path.join(base,'归档清单.json'),'utf8'));
const errors=[];
const verified=[];
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
for(const c of m.conversations){
  const raw=await fs.readFile(path.resolve('work/drive-import-20261027',c.id+'.raw'));
  if(raw.length!==c.bytes||sha(raw)!==c.raw_sha256)errors.push('source fingerprint '+c.key);
  if(c.local){
    const text=await fs.readFile(path.join(base,c.local),'utf8');
    for(const n of c.kept_turns)if(!text.includes('id="turn-'+n+'"'))errors.push('missing turn '+c.key+':'+n);
    for(const n of c.dropped_turns)if(text.includes('id="turn-'+n+'"'))errors.push('retained dropped turn '+c.key+':'+n);
  }
}
for(const a of m.assets.filter(a=>a.local)){
  const b=await fs.readFile(path.join(base,a.local));
  if(b.length!==a.bytes||sha(b)!==a.sha256)errors.push('asset fingerprint '+a.id);
}
const authored=['README.md','题目汇总.md','扫描清单.md','知识学习索引.md',...m.problems.map(p=>p.local)].map(p=>path.join(base,p));
authored.push(path.resolve('outputs/训练记录.md'),path.resolve('outputs/训练档案.md'),path.resolve('outputs/复盘/2026-10-27-历史补录-AGC022E.md'),path.resolve('outputs/复盘/2026-10-26-历史补录-AGC028D.md'));
let linkCount=0;
for(const p of authored){
  const text=await fs.readFile(p,'utf8');
  for(const match of text.matchAll(/\]\((<[^>]+>|[^)]+)\)/g)){
    const href=match[1].replace(/^<|>$/g,'');
    if(/^(?:https?:|mailto:|#)/.test(href))continue;
    const [target,anchor]=href.split('#');
    const dest=path.resolve(path.dirname(p),decodeURI(target));
    try{
      await fs.access(dest);
      if(anchor&&anchor.startsWith('turn-')){
        const t=await fs.readFile(dest,'utf8');
        if(!t.includes('id="'+anchor+'"'))throw new Error('anchor absent');
      }
      linkCount++;
    }catch(e){errors.push(path.relative(base,p)+' => '+href+' : '+e.message);}
  }
}
const counts={conversations:(await fs.readdir(path.join(base,'对话'))).length,problemGroups:(await fs.readdir(path.join(base,'题目'))).length,assets:(await fs.readdir(path.join(base,'附件'))).length};
if(counts.conversations!==40||counts.problemGroups!==53||counts.assets!==17)errors.push('count mismatch');
const report={date:'2026-10-27',sourceByteAndHashChecks:64,assetByteAndHashChecks:17,authoredLocalLinks:linkCount,counts,missingHistoricalAssets:m.counts.missingAssets,errors};
await fs.writeFile(path.join(base,'核对结果.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report));
if(errors.length)process.exitCode=1;

